mapper.select:
SELECT kb_question.*, EXISTS(
    SELECT 1 FROM kb_question_source exam_qs JOIN kb_source exam_s ON exam_s.id=exam_qs.source_id
    JOIN kb_verified_exam_source exam_e ON exam_e.source_id=exam_qs.source_id
    WHERE exam_qs.question_id=kb_question.id AND kb_question.content_kind='EXERCISE'
      AND exam_s.source_kind='EXAM' AND exam_e.authenticity_status='VERIFIED'
      AND exam_qs.match_status='VERIFIED' AND exam_qs.matched_stem_hash=kb_question.stem_hash
) AS is_real_exam FROM kb_question

    AND 
    AND kb_question.id IN #{qid}
    AND title LIKE CONCAT('%', #{title}, '%')


            AND MATCH(stem_text) AGAINST(#{query} IN NATURAL LANGUAGE MODE)
            AND stem_text LIKE CONCAT('%', #{escapedQuery}, '%') ESCAPE '!'


    AND status=#{status}
    AND subject=#{subject}
    AND content_kind=#{contentKind}
    AND layout_mode=#{layoutMode}
    AND unit_kind=#{unitKind}
    AND pagination_mode=#{paginationMode}
    AND question_type=#{questionType}
    AND difficulty=#{difficulty}
    AND creation_kind=#{creationKind}
    AND has_image=#{hasImage}



                AND id IN
                #{mid}

            AND 1=0


    AND EXISTS(SELECT 1 FROM kb_question_source qs WHERE qs.question_id=kb_question.id AND qs.source_id=#{sourceId})

      AND EXISTS(SELECT 1 FROM kb_question_source vqs JOIN kb_source vs ON vs.id=vqs.source_id JOIN kb_exam_source ve ON ve.source_id=vqs.source_id
        WHERE vqs.question_id=kb_question.id AND vs.source_kind='EXAM'
        AND kb_question.content_kind='EXERCISE' AND vqs.match_status='VERIFIED' AND vqs.matched_stem_hash=kb_question.stem_hash AND EXISTS(SELECT 1 FROM kb_verified_exam_source valid WHERE valid.source_id=ve.source_id)
          AND vqs.source_id=#{sourceId}
        AND vqs.source_id=#{examSourceId}
        AND ve.exam_type=#{examPurpose}AND ve.exam_year=#{examYear}
        AND EXISTS(SELECT 1 FROM kb_source_region rg WHERE rg.source_id=vqs.source_id AND rg.region_role='EXAM_SCOPE' AND rg.region_code IN #{code})
      )

    AND EXISTS(SELECT 1 FROM kb_question_source wqs JOIN kb_occurrence_collection wc ON wc.occurrence_id=wqs.id AND wc.collection_kind='WRONG_QUESTION' WHERE wqs.question_id=kb_question.id AND wqs.source_id=#{wrongSourceId})
    AND EXISTS(SELECT 1 FROM kb_question_kp qk JOIN kb_kp_outline ko ON ko.kp_id=qk.kp_id WHERE qk.question_id=kb_question.id AND ko.outline_id=#{outlineId})
    AND EXISTS(SELECT 1 FROM kb_question_kp qk JOIN kb_outline_node_kp nk ON nk.kp_id=qk.kp_id WHERE qk.question_id=kb_question.id AND nk.node_id=#{outlineNodeId})



                AND EXISTS(SELECT 1 FROM kb_question_source qs JOIN kb_source s ON s.id=qs.source_id
                LEFT JOIN kb_verified_exam_source e ON e.source_id=qs.source_id WHERE qs.question_id=kb_question.id AND qs.source_id IN
                #{sid}
                AND s.source_kind='EXAM' AND e.authenticity_status='VERIFIED' AND qs.match_status='VERIFIED' AND qs.matched_stem_hash=kb_question.stem_hash
                )

            AND 1=0



 ORDER BY id DESC

SELECT question_id AS questionId,kp_id AS kpId FROM kb_question_kp
WHERE question_id IN #{id}
ORDER BY question_id,kp_id
